--- a/hosts/gpu/src/native_artifact/program/codegen/numeric_binary.rs
+++ b/hosts/gpu/src/native_artifact/program/codegen/numeric_binary.rs
@@ -0,0 +1,235 @@
+//! Source-selected elementwise F64 loops over one checked synchronous loan.
+//! Flat scalar/exact broadcasts use independent SIMD lanes, with scalar tails.
+use super::hooks::Hooks;
+use crate::native_artifact::program::{
+    prepare::numeric_binary::Operation,
+    protocol::{GlobalHelper, abi::NumericBinaryFrame as Frame},
+};
+use crate::native_artifact::{
+    NativeCompileError,
+    compiler::{backend, f64_arithmetic, guard},
+};
+use cranelift_codegen::ir::{Block, InstBuilder, MemFlags, Value, condcodes::IntCC, types};
+use cranelift_frontend::FunctionBuilder;
+use mech_engine::native_artifact::NativeMatchValue;
+use std::mem::offset_of;
+
+fn get(b: &mut FunctionBuilder<'_>, frame: Value, offset: usize) -> Value {
+    b.ins()
+        .load(types::I64, MemFlags::new(), frame, offset as i32)
+}
+fn address(b: &mut FunctionBuilder<'_>, pointer: Value, index: Value) -> Value {
+    let bytes = b.ins().imul_imm(index, 8);
+    b.ins().iadd(pointer, bytes)
+}
+fn scalar_at(
+    b: &mut FunctionBuilder<'_>,
+    pointer: Value,
+    scalar: Value,
+    mode: Value,
+    index: Value,
+    columns: Value,
+) -> Value {
+    let plain = b.create_block();
+    let matrix = b.create_block();
+    let done = b.create_block();
+    b.append_block_param(done, types::F64);
+    let is_scalar = b.ins().icmp_imm(IntCC::Equal, mode, 0);
+    b.ins().brif(is_scalar, plain, &[], matrix, &[]);
+    b.switch_to_block(plain);
+    let value = b.ins().bitcast(types::F64, MemFlags::new(), scalar);
+    b.ins().jump(done, &[value.into()]);
+    b.switch_to_block(matrix);
+    // A nonempty output certifies nonzero columns. Every mode and physical
+    // span was checked against current canonical geometry before this loan.
+    let row = b.ins().udiv(index, columns);
+    let column = b.ins().urem(index, columns);
+    let is_column = b.ins().icmp_imm(IntCC::Equal, mode, 2);
+    let coordinate = b.ins().select(is_column, row, column);
+    let exact = b.ins().icmp_imm(IntCC::Equal, mode, 1);
+    let ordinal = b.ins().select(exact, index, coordinate);
+    let pointer = address(b, pointer, ordinal);
+    let value = b.ins().load(types::F64, MemFlags::new(), pointer, 0);
+    b.ins().jump(done, &[value.into()]);
+    b.switch_to_block(done);
+    b.block_params(done)[0]
+}
+fn flat(
+    b: &mut FunctionBuilder<'_>,
+    op: &Operation,
+    left: Value,
+    right: Value,
+    sleft: Value,
+    sright: Value,
+    output: Value,
+    count: Value,
+    left_scalar: bool,
+    right_scalar: bool,
+    done: Block,
+) {
+    let vector_type = types::F64.by(2).expect("two F64 lanes");
+    let scalar_left = b.ins().bitcast(types::F64, MemFlags::new(), sleft);
+    let scalar_right = b.ins().bitcast(types::F64, MemFlags::new(), sright);
+    let splat_left = left_scalar.then(|| b.ins().splat(vector_type, scalar_left));
+    let splat_right = right_scalar.then(|| b.ins().splat(vector_type, scalar_right));
+    let index = b.declare_var(types::I64);
+    let zero = b.ins().iconst(types::I64, 0);
+    b.def_var(index, zero);
+    let header = b.create_block();
+    let body = b.create_block();
+    let tail = b.create_block();
+    b.ins().jump(header, &[]);
+    b.switch_to_block(header);
+    let at = b.use_var(index);
+    let remaining = b.ins().isub(count, at);
+    let pair = b
+        .ins()
+        .icmp_imm(IntCC::UnsignedGreaterThanOrEqual, remaining, 2);
+    b.ins().brif(pair, body, &[], tail, &[]);
+    b.switch_to_block(body);
+    let a = if let Some(value) = splat_left {
+        value
+    } else {
+        let p = address(b, left, at);
+        b.ins().load(vector_type, MemFlags::new(), p, 0)
+    };
+    let c = if let Some(value) = splat_right {
+        value
+    } else {
+        let p = address(b, right, at);
+        b.ins().load(vector_type, MemFlags::new(), p, 0)
+    };
+    let next = f64_arithmetic(b, op.op, a, c);
+    let p = address(b, output, at);
+    b.ins().store(MemFlags::new(), next, p, 0);
+    let advanced = b.ins().iadd_imm(at, 2);
+    b.def_var(index, advanced);
+    b.ins().jump(header, &[]);
+    b.switch_to_block(tail);
+    let at = b.use_var(index);
+    let has_tail = b.ins().icmp(IntCC::UnsignedLessThan, at, count);
+    let single = b.create_block();
+    b.ins().brif(has_tail, single, &[], done, &[]);
+    b.switch_to_block(single);
+    let a = if left_scalar {
+        scalar_left
+    } else {
+        let p = address(b, left, at);
+        b.ins().load(types::F64, MemFlags::new(), p, 0)
+    };
+    let c = if right_scalar {
+        scalar_right
+    } else {
+        let p = address(b, right, at);
+        b.ins().load(types::F64, MemFlags::new(), p, 0)
+    };
+    let next = f64_arithmetic(b, op.op, a, c);
+    let p = address(b, output, at);
+    b.ins().store(MemFlags::new(), next, p, 0);
+    b.ins().jump(done, &[]);
+}
+/// Leaves the builder at the original ordinary call on refusal. The returned
+/// join is reached only after that call or successful native publication.
+pub(in crate::native_artifact) fn emit_entry(
+    b: &mut FunctionBuilder<'_>,
+    hooks: &Hooks,
+    site: usize,
+    op: &Operation,
+    operands: &[NativeMatchValue],
+    locals: Value,
+    is_scalar: impl Fn(NativeMatchValue) -> bool,
+    error: Block,
+) -> Result<Block, NativeCompileError> {
+    if operands.iter().map(|v| v.get()).collect::<Vec<_>>() != op.operands {
+        return Err(backend("matrix arithmetic source operands differ"));
+    }
+    hooks.library_operation(
+        b,
+        site,
+        GlobalHelper::NumericBinaryPrepare.raw(),
+        operands,
+        locals,
+        is_scalar,
+        error,
+    )?;
+    let frame = b.ins().load(types::I64, MemFlags::new(), hooks.result, 0);
+    let native = b.create_block();
+    let ordinary = b.create_block();
+    let joined = b.create_block();
+    b.ins().brif(frame, native, &[], ordinary, &[]);
+    b.switch_to_block(native);
+    let left = get(b, frame, offset_of!(Frame, left));
+    let right = get(b, frame, offset_of!(Frame, right));
+    let output = get(b, frame, offset_of!(Frame, output));
+    let count = get(b, frame, offset_of!(Frame, count));
+    let columns = get(b, frame, offset_of!(Frame, columns));
+    let lmode = get(b, frame, offset_of!(Frame, left_mode));
+    let rmode = get(b, frame, offset_of!(Frame, right_mode));
+    let sleft = get(b, frame, offset_of!(Frame, left_scalar));
+    let sright = get(b, frame, offset_of!(Frame, right_scalar));
+    let complete = b.create_block();
+    let flat_entry = b.create_block();
+    let strided = b.create_block();
+    let lf = b.ins().icmp_imm(IntCC::UnsignedLessThanOrEqual, lmode, 1);
+    let rf = b.ins().icmp_imm(IntCC::UnsignedLessThanOrEqual, rmode, 1);
+    let both = b.ins().band(lf, rf);
+    b.ins().brif(both, flat_entry, &[], strided, &[]);
+    b.switch_to_block(flat_entry);
+    let ls = b.ins().icmp_imm(IntCC::Equal, lmode, 0);
+    let rs = b.ins().icmp_imm(IntCC::Equal, rmode, 0);
+    let lscalar = b.create_block();
+    let lexact = b.create_block();
+    b.ins().brif(ls, lscalar, &[], lexact, &[]);
+    for (block, scalar) in [(lscalar, true), (lexact, false)] {
+        b.switch_to_block(block);
+        let rscalar = b.create_block();
+        let rexact = b.create_block();
+        b.ins().brif(rs, rscalar, &[], rexact, &[]);
+        for (block, rscalar) in [(rscalar, true), (rexact, false)] {
+            b.switch_to_block(block);
+            flat(
+                b, op, left, right, sleft, sright, output, count, scalar, rscalar, complete,
+            );
+        }
+    }
+    b.switch_to_block(strided);
+    let index = b.declare_var(types::I64);
+    let zero = b.ins().iconst(types::I64, 0);
+    b.def_var(index, zero);
+    let header = b.create_block();
+    let body = b.create_block();
+    b.ins().jump(header, &[]);
+    b.switch_to_block(header);
+    let at = b.use_var(index);
+    let valid = b.ins().icmp(IntCC::UnsignedLessThan, at, count);
+    b.ins().brif(valid, body, &[], complete, &[]);
+    b.switch_to_block(body);
+    let a = scalar_at(b, left, sleft, lmode, at, columns);
+    let c = scalar_at(b, right, sright, rmode, at, columns);
+    let next = f64_arithmetic(b, op.op, a, c);
+    let p = address(b, output, at);
+    b.ins().store(MemFlags::new(), next, p, 0);
+    let next = b.ins().iadd_imm(at, 1);
+    b.def_var(index, next);
+    b.ins().jump(header, &[]);
+    b.switch_to_block(complete);
+    let zero = b.ins().iconst(types::I64, 0);
+    hooks.call(
+        b,
+        site,
+        GlobalHelper::NumericBinaryFinish,
+        [frame, count, zero],
+        error,
+    );
+    let ready = b.ins().load(types::I64, MemFlags::new(), hooks.result, 0);
+    let valid = b.ins().icmp_imm(IntCC::Equal, ready, 1);
+    guard(
+        b,
+        valid,
+        error,
+        crate::native_artifact::abi::STATUS_INTEGRITY,
+    );
+    b.ins().jump(joined, &[]);
+    b.switch_to_block(ordinary);
+    Ok(joined)
+}

--- a/hosts/gpu/src/native_artifact/program/prepare/numeric_binary.rs
+++ b/hosts/gpu/src/native_artifact/program/prepare/numeric_binary.rs
@@ -0,0 +1,54 @@
+//! Same-plan selected elementwise arithmetic; no values, pointers or permits.
+use mech_engine::native_artifact::{
+    NativeIterationAction as Action, NativeProgramArtifactPlan as Plan, NativeScalarOp,
+};
+pub(in crate::native_artifact) const HEADER_WORK: u64 = 32768;
+#[derive(Clone, Debug, Eq, PartialEq)]
+pub(in crate::native_artifact) struct Operation {
+    pub operands: [u32; 2],
+    pub output: u32,
+    pub op: NativeScalarOp,
+}
+#[derive(Debug)]
+pub(in crate::native_artifact) struct Layout {
+    sites: Box<[Option<Operation>]>,
+}
+impl Layout {
+    pub fn derive(plan: &Plan) -> Result<Self, &'static str> {
+        plan.validate_current_visits()?;
+        let sites = plan
+            .blocks()
+            .iter()
+            .enumerate()
+            .map(|(site, block)| {
+                let Action::LibraryCall {
+                    operands, output, ..
+                } = block.action()
+                else {
+                    return Ok(None);
+                };
+                let Some(template) = plan.prepared_library_template(site)? else {
+                    return Ok(None);
+                };
+                if operands.len() != 2
+                    || operands
+                        .iter()
+                        .zip(template.inputs())
+                        .any(|(v, s)| plan.values()[v.get() as usize].definition() != s)
+                    || plan.values()[output.get() as usize].definition() != template.output()
+                {
+                    return Ok(None);
+                }
+                Ok(template.f64_matrix_binary_op().map(|op| Operation {
+                    operands: [operands[0].get(), operands[1].get()],
+                    output: output.get(),
+                    op,
+                }))
+            })
+            .collect::<Result<Box<[_]>, &'static str>>()?;
+        Ok(Self { sites })
+    }
+    pub fn at(&self, site: usize) -> Option<&Operation> {
+        self.sites.get(site)?.as_ref()
+    }
+}

--- a/hosts/gpu/src/native_artifact/program/runtime/composition_tests/numeric_binary.rs
+++ b/hosts/gpu/src/native_artifact/program/runtime/composition_tests/numeric_binary.rs
@@ -0,0 +1,292 @@
+//! Exact IEEE results, shared broadcasts, actual selection and funded fallback.
+use super::*;
+use crate::native_artifact::codegen::options::OptimizationPass;
+use mech_core::snapshot::F64Bits;
+
+fn data(values: &[f64]) -> Data {
+    Data::Matrix(
+        values
+            .iter()
+            .map(|v| Data::F64(F64Bits::from_f64(*v)))
+            .collect(),
+    )
+}
+fn completed(counts: &observe::Counts) -> u64 {
+    counts
+        .helpers
+        .iter()
+        .filter(|((_, op), _)| *op == GlobalHelper::NumericBinaryFinish.raw())
+        .map(|(_, n)| n)
+        .sum()
+}
+fn outputs(values: &[Option<Value>]) -> Vec<Data> {
+    values
+        .iter()
+        .map(|v| v.as_ref().unwrap().canonical_data_draft().unwrap())
+        .collect()
+}
+
+#[test]
+fn numeric_binary_broadcasts_simd_tails_and_dynamic_shapes_match_ordinary_bits() {
+    let shapes = [
+        ([2, 3], [2, 3]),
+        ([3, 3], [3, 3]),
+        ([2, 3], [1, 3]),
+        ([2, 3], [2, 1]),
+        ([1, 3], [2, 1]),
+        ([2, 1], [1, 3]),
+        ([1, 1], [2, 3]),
+        ([2, 3], [1, 1]),
+        ([1, 1], [1, 1]),
+        ([0, 3], [0, 3]),
+        ([2, 0], [2, 0]),
+    ];
+    for operator in ["+", "-", "*", "/"] {
+        for scalar in [0, 1, 2] {
+            let left = if scalar == 1 { "f64" } else { "[f64]" };
+            let right = if scalar == 2 { "f64" } else { "[f64]" };
+            let source = format!("input<{left}> {operator} peer<{right}>\n");
+            for artifact in artifacts(&source) {
+                let mode = NativeProgramLimitMode::NoLimits;
+                let catalog = mech_stdlib::source_catalog();
+                let native = JitProgramArtifact::compile(&artifact, &catalog).unwrap();
+                let ordinary = JitProgramArtifact::compile_for_test(
+                    &artifact,
+                    &catalog,
+                    OptimizationPass::NumericElementwise,
+                )
+                .unwrap();
+                assert_eq!(
+                    native
+                        .descriptor()
+                        .metadata()
+                        .plan
+                        .blocks()
+                        .iter()
+                        .enumerate()
+                        .filter(|(i, _)| native
+                            .descriptor()
+                            .metadata()
+                            .numeric_binary
+                            .at(*i)
+                            .is_some())
+                        .count(),
+                    1
+                );
+                for (ld, rd) in shapes {
+                    let memory = mode.memory_budget();
+                    let left = (0..ld[0] * ld[1])
+                        .map(|i| if i % 3 == 0 { -0.0 } else { i as f64 + 0.25 })
+                        .collect::<Vec<_>>();
+                    let right = (0..rd[0] * rd[1])
+                        .map(|i| if i % 2 == 0 { -2.0 } else { 0.0 })
+                        .collect::<Vec<_>>();
+                    let ldata = if scalar == 1 {
+                        Data::F64(F64Bits::from_f64(-0.0))
+                    } else {
+                        data(&left)
+                    };
+                    let rdata = if scalar == 2 {
+                        Data::F64(F64Bits::from_f64(2.0))
+                    } else {
+                        data(&right)
+                    };
+                    let args = numeric_maps::typed_arguments(
+                        &artifact,
+                        &memory,
+                        &[
+                            ("input", ldata, if scalar == 1 { &[] } else { &ld }),
+                            ("peer", rdata, if scalar == 2 { &[] } else { &rd }),
+                        ],
+                    );
+                    let before = contents(&args);
+                    let baseline = (memory.used_bytes(), memory.retained_snapshot_nodes());
+                    let mut actual = vec![None; artifact.outputs().len()];
+                    let mut expected = actual.clone();
+                    let (a, counts) =
+                        observe::run(&native, &args, &mut actual, mode.execution(), &memory);
+                    let (b, ordinary_counts) =
+                        observe::run(&ordinary, &args, &mut expected, mode.execution(), &memory);
+                    assert_eq!(
+                        a.is_ok(),
+                        b.is_ok(),
+                        "{source} {ld:?} {rd:?}: {a:?} / {b:?}"
+                    );
+                    if let (Ok(a), Ok(b)) = (a, b) {
+                        assert_eq!(
+                            outputs(&actual),
+                            outputs(&expected),
+                            "{source} {ld:?} {rd:?}"
+                        );
+                        assert_eq!(
+                            completed(&counts),
+                            1,
+                            "selected {source} {ld:?} {rd:?}: {:?}",
+                            counts.helpers
+                        );
+                        assert_eq!(completed(&ordinary_counts), 0);
+                        assert!(a.work >= b.work, "complete source cost must not be reduced");
+                        assert!(a.comparison_work >= b.comparison_work);
+                        let aliases = actual.clone();
+                        let (retry, counts) = observe::run_restored(
+                            &native,
+                            &args,
+                            &mut actual,
+                            mode.execution(),
+                            &memory,
+                        );
+                        assert!(retry.is_ok(), "restored: {retry:?}");
+                        assert_eq!(completed(&counts), 1);
+                        assert_eq!(outputs(&actual), outputs(&aliases));
+                    }
+                    assert_eq!(contents(&args), before);
+                    drop((actual, expected));
+                    assert_eq!(
+                        (memory.used_bytes(), memory.retained_snapshot_nodes()),
+                        baseline
+                    );
+                    drop(args);
+                    assert_eq!(
+                        (memory.used_bytes(), memory.retained_snapshot_nodes()),
+                        (0, 0)
+                    );
+                }
+            }
+        }
+    }
+}
+
+#[test]
+fn numeric_binary_input_nan_falls_back_and_generated_nan_keeps_exact_payload() {
+    for operator in ["+", "-", "*", "/"] {
+        for artifact in artifacts(&format!("input<[f64]> {operator} peer<[f64]>\n")) {
+            let mode = NativeProgramLimitMode::NoLimits;
+            let catalog = mech_stdlib::source_catalog();
+            let native = JitProgramArtifact::compile(&artifact, &catalog).unwrap();
+            let ordinary = JitProgramArtifact::compile_for_test(
+                &artifact,
+                &catalog,
+                OptimizationPass::NumericElementwise,
+            )
+            .unwrap();
+            for input_nan in [false, true] {
+                let memory = mode.memory_budget();
+                let left = if input_nan {
+                    vec![
+                        f64::from_bits(0xfff8000000000037),
+                        f64::from_bits(0x7ff0000000000042),
+                        0.0,
+                    ]
+                } else {
+                    vec![f64::INFINITY, f64::NEG_INFINITY, 0.0]
+                };
+                let right = vec![f64::NEG_INFINITY, f64::NEG_INFINITY, 0.0];
+                let args = numeric_maps::typed_arguments(
+                    &artifact,
+                    &memory,
+                    &[
+                        ("input", data(&left), &[1, 3]),
+                        ("peer", data(&right), &[1, 3]),
+                    ],
+                );
+                let mut actual = vec![None; artifact.outputs().len()];
+                let mut expected = actual.clone();
+                let (a, counts) =
+                    observe::run(&native, &args, &mut actual, mode.execution(), &memory);
+                let (b, _) =
+                    observe::run(&ordinary, &args, &mut expected, mode.execution(), &memory);
+                a.unwrap();
+                b.unwrap();
+                assert_eq!(
+                    outputs(&actual),
+                    outputs(&expected),
+                    "{operator}, input_nan={input_nan}"
+                );
+                assert_eq!(completed(&counts), u64::from(!input_nan));
+                drop((actual, expected, args));
+                assert_eq!(
+                    (memory.used_bytes(), memory.retained_snapshot_nodes()),
+                    (0, 0)
+                );
+            }
+        }
+    }
+}
+
+#[test]
+fn numeric_binary_finite_caps_decline_without_losing_aliases_or_retry() {
+    for artifact in artifacts("input<[f64]> + peer<[f64]>\n") {
+        let mode = NativeProgramLimitMode::NoLimits;
+        let catalog = mech_stdlib::source_catalog();
+        let native = JitProgramArtifact::compile(&artifact, &catalog).unwrap();
+        let ordinary = JitProgramArtifact::compile_for_test(
+            &artifact,
+            &catalog,
+            OptimizationPass::NumericElementwise,
+        )
+        .unwrap();
+        let memory = mode.memory_budget();
+        let args = numeric_maps::typed_arguments(
+            &artifact,
+            &memory,
+            &[
+                ("input", data(&[1., 2., 3.]), &[1, 3]),
+                ("peer", data(&[4., 5., 6.]), &[1, 3]),
+            ],
+        );
+        let mut prior = vec![None; artifact.outputs().len()];
+        observe::run(&native, &args, &mut prior, mode.execution(), &memory)
+            .0
+            .unwrap();
+        let baseline = (memory.used_bytes(), memory.retained_snapshot_nodes());
+        for field in 0..12 {
+            let mut policy = mode.execution();
+            match field {
+                0 => policy.library.max_output_elements = Some(0),
+                1 => policy.library.max_output_bytes = Some(0),
+                2 => policy.library.max_temporary_bytes = Some(0),
+                3 => policy.library.max_cloned_bytes = Some(0),
+                4 => policy.library.max_retained_nodes = Some(0),
+                5 => policy.library.max_compute_work = Some(0),
+                6 => policy.library.max_comparison_work = Some(0),
+                7 => policy.library.max_scalar_instructions = None,
+                8 => policy.library.max_transfer_bytes = None,
+                9 => policy.library.max_storage_buffer_bytes = None,
+                10 => policy.library.max_storage_bindings = None,
+                11 => policy.execution.max_work = 1,
+                _ => unreachable!(),
+            }
+            let mut actual = prior.clone();
+            let mut expected = prior.clone();
+            let (a, counts) = observe::run(&native, &args, &mut actual, policy, &memory);
+            let (b, _) = observe::run(&ordinary, &args, &mut expected, policy, &memory);
+            assert_eq!(a.is_ok(), b.is_ok(), "field {field}: {a:?} / {b:?}");
+            assert_eq!(completed(&counts), 0);
+            assert_eq!(outputs(&actual), outputs(&expected));
+            if a.is_err() {
+                for (a, p) in actual.iter().zip(&prior) {
+                    assert!(
+                        a.as_ref()
+                            .unwrap()
+                            .shares_frozen_storage(p.as_ref().unwrap())
+                    );
+                }
+            }
+            drop((actual, expected));
+            assert_eq!(
+                (memory.used_bytes(), memory.retained_snapshot_nodes()),
+                baseline
+            );
+        }
+        let mut output = prior.clone();
+        let (result, counts) = observe::run(&native, &args, &mut output, mode.execution(), &memory);
+        result.unwrap();
+        assert_eq!(completed(&counts), 1);
+        assert_eq!(outputs(&output), outputs(&prior));
+        drop((output, prior, args));
+        assert_eq!(
+            (memory.used_bytes(), memory.retained_snapshot_nodes()),
+            (0, 0)
+        );
+    }
+}

--- a/hosts/gpu/src/native_artifact/program/runtime/composition_tests/numeric_composition_diagnostic.rs
+++ b/hosts/gpu/src/native_artifact/program/runtime/composition_tests/numeric_composition_diagnostic.rs
