+                assert_eq!(
+                    (memory.used_bytes(), memory.retained_snapshot_nodes()),
+                    baseline
+                );
+            }
+            drop((prior, args));
+            assert_eq!(
+                (memory.used_bytes(), memory.retained_snapshot_nodes()),
+                (0, 0)
+            );
+        }
+    }
