+            || self.state.consumed
+            || args != [pointer, pending.cells.len() as u64, 0]
+            || pending.reservation.budget() != self.state.library.memory_budget()
+            || pending.frame.output != pending.cells.as_mut_ptr() as u64
+            || pending.frame.count != pending.cells.len() as u64
