+                persistent_bytes: published,
+                turn_peak_bytes: temporary,
+                cloned_bytes: temporary,
+                retained_nodes: nodes,
+                output_elements: output,
+                work: WorkDemand {
+                    compute,
+                    comparison,
+                    ..Default::default()
+                },
+                ..Default::default()
+            },
+            replay,
+        ))
+    }
+}

